//! Crash recovery storage: unsaved work kept in the app data directory so it
//! survives a crash or a closed window (`RecoveryStore` in the frontend).
//!
//! ```text
//! recovery/<id>/meta.json      { title, savedAt }
//! recovery/<id>/snapshot.json  the editor's recovery snapshot (UTF-8 JSON)
//! recovery/<id>/files/<key>    PDFs and images the snapshot refers to
//! ```
//!
//! Record ids and file keys are generated by Folio. Anything that does not
//! match `^[A-Za-z0-9_-]{1,128}$`, and Windows device names such as `CON`,
//! is refused before a path is built from it.

use crate::paths;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::sync::{Mutex, MutexGuard};
use std::time::{Duration, SystemTime};

pub const MAX_SNAPSHOT_BYTES: u64 = 64 * 1024 * 1024;
pub const MAX_FILE_BYTES: u64 = 1024 * 1024 * 1024;
pub const MAX_TOTAL_BYTES: u64 = 4 * 1024 * 1024 * 1024;
/// Record folders without a snapshot are deleted after this long.
pub const ORPHAN_AGE: Duration = Duration::from_secs(60 * 60);
const MAX_TITLE_CHARS: usize = 500;
const MAX_META_BYTES: u64 = 64 * 1024;
const META: &str = "meta.json";
const SNAPSHOT: &str = "snapshot.json";
const FILES: &str = "files";

/// Headers of `recovery_save_snapshot` and `recovery_save_file`, whose
/// request bodies are the raw data.
pub const ID_HEADER: &str = "x-folio-recovery-id";
pub const KEY_HEADER: &str = "x-folio-recovery-key";
/// Percent-encoded, like file names.
pub const TITLE_HEADER: &str = "x-folio-recovery-title";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Limits {
    pub snapshot: u64,
    pub file: u64,
    /// Everything in the recovery folder together.
    pub total: u64,
}

impl Default for Limits {
    fn default() -> Self {
        Limits {
            snapshot: MAX_SNAPSHOT_BYTES,
            file: MAX_FILE_BYTES,
            total: MAX_TOTAL_BYTES,
        }
    }
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum RecoveryError {
    #[error("The recovery data was not understood.")]
    InvalidName,
    #[error("The recovery data was not understood.")]
    InvalidRequest,
    #[error("This document is too large to keep for recovery.")]
    TooLarge,
    #[error("Folio has no room left for recovery data (4 GB). Save or close documents with unsaved changes.")]
    Full,
    #[error("The recovery data could not be found.")]
    NotFound,
    #[error("Recovery data cannot be stored on this computer.")]
    Unavailable,
    #[error("The recovery data could not be read or written.")]
    Io,
}

impl RecoveryError {
    pub fn code(&self) -> &'static str {
        match self {
            RecoveryError::InvalidName => "invalid-name",
            RecoveryError::InvalidRequest => "invalid-request",
            RecoveryError::TooLarge => "too-large",
            RecoveryError::Full => "recovery-full",
            RecoveryError::NotFound => "not-found",
            RecoveryError::Unavailable => "unavailable",
            RecoveryError::Io => "storage-failed",
        }
    }
}

/// `RecoveryRecord` in the frontend.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RecoveryRecord {
    pub id: String,
    pub title: String,
    pub saved_at: String,
    /// Snapshot and files together.
    pub byte_length: u64,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Meta {
    title: String,
    saved_at: String,
}

/// Record ids and file keys: `^[A-Za-z0-9_-]{1,128}$`, except names Windows
/// reserves for devices (checked everywhere, so records stay portable).
pub fn is_valid_name(name: &str) -> bool {
    (1..=128).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-')
        && !is_reserved_device_name(name)
}

/// `CON`, `PRN`, `AUX`, `NUL`, `COM0`–`COM9` and `LPT0`–`LPT9`, in any case
/// and with any extension: Windows opens the device instead of a file.
pub fn is_reserved_device_name(name: &str) -> bool {
    let stem = name.split('.').next().unwrap_or_default().trim_end();
    let upper = stem.to_ascii_uppercase();
    match upper.as_bytes() {
        b"CON" | b"PRN" | b"AUX" | b"NUL" => true,
        [b'C', b'O', b'M', digit] | [b'L', b'P', b'T', digit] => digit.is_ascii_digit(),
        _ => false,
    }
}

fn clean_title(title: &str) -> String {
    let printable: String = title.chars().filter(|c| !c.is_control()).collect();
    let short: String = printable.trim().chars().take(MAX_TITLE_CHARS).collect();
    short.trim_end().to_owned()
}

fn io_error(error: std::io::Error) -> RecoveryError {
    if error.kind() == std::io::ErrorKind::NotFound {
        RecoveryError::NotFound
    } else {
        RecoveryError::Io
    }
}

fn file_len(path: &Path) -> u64 {
    std::fs::symlink_metadata(path)
        .map(|metadata| metadata.len())
        .unwrap_or(0)
}

/// Total size of the regular files below `dir`. Folio never creates links,
/// so none are followed.
fn tree_size(dir: &Path) -> u64 {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return 0;
    };
    entries
        .flatten()
        .map(|entry| match entry.file_type() {
            Ok(kind) if kind.is_dir() => tree_size(&entry.path()),
            Ok(kind) if kind.is_file() => entry.metadata().map(|m| m.len()).unwrap_or(0),
            _ => 0,
        })
        .sum()
}

pub struct RecoveryStore {
    base: PathBuf,
    limits: Limits,
    /// Writes are serialized so the size limit holds.
    writes: Mutex<()>,
    /// Whether [`RecoveryStore::list`] deletes abandoned record folders.
    sweep: bool,
}

impl RecoveryStore {
    pub fn new(base: PathBuf) -> Self {
        Self::with_limits(base, Limits::default())
    }

    pub fn with_limits(base: PathBuf, limits: Limits) -> Self {
        RecoveryStore {
            base,
            limits,
            writes: Mutex::new(()),
            sweep: true,
        }
    }

    /// Leaves abandoned record folders alone: another copy of Folio, which
    /// may still be writing them, uses the same folder.
    pub fn without_orphan_sweep(mut self) -> Self {
        self.sweep = false;
        self
    }

    fn lock(&self) -> MutexGuard<'_, ()> {
        self.writes
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    fn record_dir(&self, id: &str) -> Result<PathBuf, RecoveryError> {
        if !is_valid_name(id) {
            return Err(RecoveryError::InvalidName);
        }
        Ok(self.base.join(id))
    }

    fn file_path(&self, id: &str, key: &str) -> Result<PathBuf, RecoveryError> {
        let dir = self.record_dir(id)?;
        if !is_valid_name(key) {
            return Err(RecoveryError::InvalidName);
        }
        Ok(dir.join(FILES).join(key))
    }

    fn read_meta(dir: &Path) -> Option<Meta> {
        let bytes = paths::read_limited(&dir.join(META), MAX_META_BYTES).ok()?;
        serde_json::from_slice(&bytes).ok()
    }

    /// A complete record (meta and snapshot), if `dir` holds one.
    fn record(id: String, dir: &Path) -> Option<RecoveryRecord> {
        let meta = Self::read_meta(dir)?;
        let snapshot = std::fs::metadata(dir.join(SNAPSHOT)).ok()?;
        Some(RecoveryRecord {
            id,
            title: meta.title,
            saved_at: meta.saved_at,
            byte_length: snapshot.len() + tree_size(&dir.join(FILES)),
        })
    }

    /// When something was last written to a record folder.
    fn last_written(dir: &Path) -> Option<SystemTime> {
        let modified = |path: &Path| std::fs::metadata(path).and_then(|m| m.modified()).ok();
        modified(dir).max(modified(&dir.join(FILES)))
    }

    fn is_abandoned(dir: &Path, now: SystemTime) -> bool {
        let stale = Self::last_written(dir)
            .is_none_or(|written| now.duration_since(written).unwrap_or_default() > ORPHAN_AGE);
        stale && Self::record(String::new(), dir).is_none()
    }

    /// Records with a snapshot, newest first. Folders that never got a
    /// snapshot (an autosave that did not finish) are deleted once they
    /// were left alone for an hour, so they stop counting against the limit.
    pub fn list(&self) -> Result<Vec<RecoveryRecord>, RecoveryError> {
        self.list_at(SystemTime::now())
    }

    fn list_at(&self, now: SystemTime) -> Result<Vec<RecoveryRecord>, RecoveryError> {
        let entries = match std::fs::read_dir(&self.base) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(_) => return Err(RecoveryError::Io),
        };
        let mut records = Vec::new();
        let mut abandoned = Vec::new();
        for entry in entries.flatten() {
            let Ok(id) = entry.file_name().into_string() else {
                continue;
            };
            if !is_valid_name(&id) || !entry.file_type().is_ok_and(|kind| kind.is_dir()) {
                continue;
            }
            let dir = entry.path();
            match Self::record(id, &dir) {
                Some(record) => records.push(record),
                None if self.sweep && Self::is_abandoned(&dir, now) => abandoned.push(dir),
                None => {}
            }
        }
        if !abandoned.is_empty() {
            let _guard = self.lock();
            for dir in abandoned {
                // A save may have completed the record in the meantime.
                if Self::is_abandoned(&dir, now) {
                    let _ = std::fs::remove_dir_all(dir);
                }
            }
        }
        records.sort_by(|a, b| b.saved_at.cmp(&a.saved_at).then_with(|| a.id.cmp(&b.id)));
        Ok(records)
    }

    /// Writes or replaces the snapshot (UTF-8 JSON) of a record.
    pub fn save_snapshot(
        &self,
        id: &str,
        title: &str,
        snapshot: &[u8],
    ) -> Result<(), RecoveryError> {
        let dir = self.record_dir(id)?;
        if snapshot.len() as u64 > self.limits.snapshot {
            return Err(RecoveryError::TooLarge);
        }
        if std::str::from_utf8(snapshot).is_err() {
            return Err(RecoveryError::InvalidRequest);
        }
        let _guard = self.lock();
        let replaced = file_len(&dir.join(SNAPSHOT));
        let total = tree_size(&self.base).saturating_sub(replaced) + snapshot.len() as u64;
        if total > self.limits.total {
            return Err(RecoveryError::Full);
        }
        paths::create_private_dir(&dir).map_err(|_| RecoveryError::Io)?;
        paths::write_atomically(&dir.join(SNAPSHOT), snapshot).map_err(|_| RecoveryError::Io)?;
        let meta = Meta {
            title: clean_title(title),
            saved_at: crate::time::now(),
        };
        let meta = serde_json::to_vec(&meta).map_err(|_| RecoveryError::Io)?;
        paths::write_atomically(&dir.join(META), &meta).map_err(|_| RecoveryError::Io)
    }

    /// Stores a file for a record unless one with this key is stored already
    /// (keys are content hashes, so autosave writes each file once).
    pub fn save_file(&self, id: &str, key: &str, bytes: &[u8]) -> Result<(), RecoveryError> {
        let path = self.file_path(id, key)?;
        if bytes.len() as u64 > self.limits.file {
            return Err(RecoveryError::TooLarge);
        }
        let _guard = self.lock();
        if path.is_file() {
            return Ok(());
        }
        if tree_size(&self.base) + bytes.len() as u64 > self.limits.total {
            return Err(RecoveryError::Full);
        }
        let folder = path.parent().ok_or(RecoveryError::Io)?;
        paths::create_private_dir(folder).map_err(|_| RecoveryError::Io)?;
        paths::write_atomically(&path, bytes).map_err(|_| RecoveryError::Io)
    }

    pub fn has_file(&self, id: &str, key: &str) -> Result<bool, RecoveryError> {
        Ok(self.file_path(id, key)?.is_file())
    }

    /// The snapshot of a record, or `None` if there is no such record.
    pub fn load_snapshot(&self, id: &str) -> Result<Option<String>, RecoveryError> {
        let dir = self.record_dir(id)?;
        if Self::read_meta(&dir).is_none() {
            return Ok(None);
        }
        match paths::read_limited(&dir.join(SNAPSHOT), self.limits.snapshot) {
            Ok(bytes) => String::from_utf8(bytes)
                .map(Some)
                .map_err(|_| RecoveryError::Io),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(_) => Err(RecoveryError::Io),
        }
    }

    pub fn load_file(&self, id: &str, key: &str) -> Result<Vec<u8>, RecoveryError> {
        let path = self.file_path(id, key)?;
        paths::read_limited(&path, self.limits.file).map_err(io_error)
    }

    /// Keys of the files stored for a record, sorted.
    pub fn file_keys(&self, id: &str) -> Result<Vec<String>, RecoveryError> {
        let dir = self.record_dir(id)?.join(FILES);
        let entries = match std::fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(_) => return Err(RecoveryError::Io),
        };
        let mut keys: Vec<String> = entries
            .flatten()
            .filter(|entry| entry.file_type().is_ok_and(|kind| kind.is_file()))
            .filter_map(|entry| entry.file_name().into_string().ok())
            // Skips temporary files of interrupted writes.
            .filter(|key| is_valid_name(key))
            .collect();
        keys.sort_unstable();
        Ok(keys)
    }

    pub fn remove(&self, id: &str) -> Result<(), RecoveryError> {
        let dir = self.record_dir(id)?;
        let _guard = self.lock();
        match std::fs::remove_dir_all(dir) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(_) => Err(RecoveryError::Io),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store() -> (tempfile::TempDir, RecoveryStore) {
        let dir = tempfile::tempdir().unwrap();
        let store = RecoveryStore::new(dir.path().join("recovery"));
        (dir, store)
    }

    #[test]
    fn round_trips_snapshots_and_files() {
        let (_dir, store) = store();
        assert_eq!(store.list().unwrap(), vec![]);
        assert_eq!(store.load_snapshot("doc-1").unwrap(), None);
        store
            .save_snapshot("doc-1", "Report.pdf", br#"{"version":1}"#)
            .unwrap();
        store.save_file("doc-1", "abc123", b"%PDF-1.7").unwrap();
        store.save_file("doc-1", "img_2", b"\x89PNG").unwrap();
        assert!(store.has_file("doc-1", "abc123").unwrap());
        assert!(!store.has_file("doc-1", "missing").unwrap());
        assert_eq!(
            store.load_snapshot("doc-1").unwrap().as_deref(),
            Some(r#"{"version":1}"#)
        );
        assert_eq!(store.file_keys("doc-1").unwrap(), ["abc123", "img_2"]);
        assert_eq!(store.load_file("doc-1", "abc123").unwrap(), b"%PDF-1.7");
        let records = store.list().unwrap();
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].id, "doc-1");
        assert_eq!(records[0].title, "Report.pdf");
        assert_eq!(records[0].byte_length, 13 + 8 + 4);
        assert!(crate::time::parse_iso8601(&records[0].saved_at).is_some());

        store.remove("doc-1").unwrap();
        store.remove("doc-1").unwrap();
        assert_eq!(store.list().unwrap(), vec![]);
        assert_eq!(store.load_snapshot("doc-1").unwrap(), None);
        assert_eq!(store.file_keys("doc-1").unwrap(), Vec::<String>::new());
        assert_eq!(
            store.load_file("doc-1", "abc123"),
            Err(RecoveryError::NotFound)
        );
    }

    #[test]
    fn replaces_snapshots_and_keeps_existing_files() {
        let (_dir, store) = store();
        store.save_snapshot("doc", "Old title", b"{}").unwrap();
        store.save_snapshot("doc", "New title", b"[1,2]").unwrap();
        store.save_file("doc", "key", b"first").unwrap();
        store.save_file("doc", "key", b"second").unwrap();
        assert_eq!(
            store.load_snapshot("doc").unwrap().as_deref(),
            Some("[1,2]")
        );
        assert_eq!(store.load_file("doc", "key").unwrap(), b"first");
        assert_eq!(store.list().unwrap()[0].title, "New title");
    }

    #[test]
    fn lists_records_newest_first() {
        let (dir, store) = store();
        for (id, saved_at) in [
            ("older", "2026-01-01T10:00:00.000Z"),
            ("newest", "2026-03-01T10:00:00.000Z"),
            ("middle", "2026-02-01T10:00:00.000Z"),
        ] {
            store.save_snapshot(id, id, b"{}").unwrap();
            let meta = format!(r#"{{"title":"{id}","savedAt":"{saved_at}"}}"#);
            std::fs::write(dir.path().join("recovery").join(id).join(META), meta).unwrap();
        }
        // Files without a snapshot (an autosave that was interrupted) and
        // folders Folio did not create are not records.
        store.save_file("orphan", "key", b"data").unwrap();
        std::fs::create_dir_all(dir.path().join("recovery").join("not valid")).unwrap();
        let ids: Vec<_> = store.list().unwrap().into_iter().map(|r| r.id).collect();
        assert_eq!(ids, ["newest", "middle", "older"]);
        // Still being written, maybe: kept for now.
        assert!(store.has_file("orphan", "key").unwrap());
    }

    #[test]
    fn deletes_records_that_never_got_a_snapshot_after_an_hour() {
        let (dir, store) = store();
        store.save_snapshot("complete", "a.pdf", b"{}").unwrap();
        store.save_file("complete", "key", b"data").unwrap();
        store.save_file("abandoned", "key", &[0; 64]).unwrap();
        let now = SystemTime::now();
        assert_eq!(store.list_at(now).unwrap().len(), 1);
        assert!(store.has_file("abandoned", "key").unwrap());

        let later = now + ORPHAN_AGE + Duration::from_secs(60);
        let ids: Vec<_> = store
            .list_at(later)
            .unwrap()
            .into_iter()
            .map(|r| r.id)
            .collect();
        assert_eq!(ids, ["complete"]);
        assert!(!store.has_file("abandoned", "key").unwrap());
        assert!(store.has_file("complete", "key").unwrap());
        // Folders Folio did not create are left alone.
        let foreign = dir.path().join("recovery").join("not valid");
        std::fs::create_dir_all(&foreign).unwrap();
        store.list_at(later).unwrap();
        assert!(foreign.exists());
    }

    #[test]
    fn another_copy_of_folio_leaves_abandoned_records_alone() {
        let dir = tempfile::tempdir().unwrap();
        let store = RecoveryStore::new(dir.path().join("recovery")).without_orphan_sweep();
        store.save_file("abandoned", "key", b"data").unwrap();
        let later = SystemTime::now() + ORPHAN_AGE + Duration::from_secs(60);
        assert!(store.list_at(later).unwrap().is_empty());
        assert!(store.has_file("abandoned", "key").unwrap());
    }

    #[test]
    fn refuses_windows_device_names() {
        let (_dir, store) = store();
        for name in [
            "CON", "con", "Prn", "aux", "NUL", "COM1", "com9", "COM0", "LPT1", "lpt9",
        ] {
            assert!(is_reserved_device_name(name), "{name}");
            assert!(!is_valid_name(name), "{name}");
            assert_eq!(
                store.save_snapshot(name, "t", b"{}"),
                Err(RecoveryError::InvalidName)
            );
            assert_eq!(
                store.save_file("doc", name, b"x"),
                Err(RecoveryError::InvalidName)
            );
        }
        assert!(is_reserved_device_name("con.txt"));
        assert!(is_reserved_device_name("NUL.tar.gz"));
        for name in ["CONSOLE", "COM10", "LPTX", "con_1", "nul-2", "COMA"] {
            assert!(is_valid_name(name), "{name}");
        }
    }

    #[test]
    fn refuses_names_that_could_escape_the_folder() {
        let (dir, store) = store();
        for name in [
            "",
            "..",
            "../x",
            "a/b",
            "a\\b",
            "a.b",
            "é",
            &"a".repeat(129),
        ] {
            assert_eq!(
                store.save_snapshot(name, "t", b"{}"),
                Err(RecoveryError::InvalidName),
                "{name:?}"
            );
            assert_eq!(
                store.save_file("doc", name, b"x"),
                Err(RecoveryError::InvalidName)
            );
            assert_eq!(store.has_file(name, "key"), Err(RecoveryError::InvalidName));
            assert_eq!(store.load_snapshot(name), Err(RecoveryError::InvalidName));
            assert_eq!(
                store.load_file("doc", name),
                Err(RecoveryError::InvalidName)
            );
            assert_eq!(store.file_keys(name), Err(RecoveryError::InvalidName));
            assert_eq!(store.remove(name), Err(RecoveryError::InvalidName));
        }
        assert!(is_valid_name(&"a".repeat(128)));
        assert!(is_valid_name("Az09_-"));
        // Nothing was created.
        assert!(!dir.path().join("recovery").exists());
    }

    #[test]
    fn refuses_snapshots_that_are_not_text() {
        let (_dir, store) = store();
        assert_eq!(
            store.save_snapshot("doc", "t", b"\xff\xfe"),
            Err(RecoveryError::InvalidRequest)
        );
        assert_eq!(store.list().unwrap(), vec![]);
    }

    #[test]
    fn enforces_the_size_limits() {
        let dir = tempfile::tempdir().unwrap();
        // The meta file ({"title":"t","savedAt":"…"}) takes 49 bytes.
        let limits = Limits {
            snapshot: 10,
            file: 20,
            total: 90,
        };
        let store = RecoveryStore::with_limits(dir.path().join("recovery"), limits);
        assert_eq!(
            store.save_snapshot("doc", "t", &[b' '; 11]),
            Err(RecoveryError::TooLarge)
        );
        assert_eq!(
            store.save_file("doc", "big", &[0; 21]),
            Err(RecoveryError::TooLarge)
        );
        store.save_snapshot("doc", "t", &[b' '; 10]).unwrap();
        store.save_file("doc", "a", &[0; 20]).unwrap();
        // The folder now holds 79 bytes.
        assert_eq!(
            store.save_file("doc", "b", &[0; 20]),
            Err(RecoveryError::Full)
        );
        assert!(!store.has_file("doc", "b").unwrap());
        // Replacing the snapshot only counts the difference.
        store.save_snapshot("doc", "t", &[b' '; 9]).unwrap();
        store.remove("doc").unwrap();
        store.save_file("doc", "b", &[0; 20]).unwrap();
    }

    #[test]
    fn keeps_titles_printable_and_short() {
        let (_dir, store) = store();
        let title = format!(" Report\u{0}\n{}", "x".repeat(600));
        store.save_snapshot("doc", &title, b"{}").unwrap();
        let stored = &store.list().unwrap()[0].title;
        assert!(stored.starts_with("Reportxxx"));
        assert_eq!(stored.chars().count(), MAX_TITLE_CHARS);
    }

    #[test]
    fn errors_never_mention_paths() {
        for error in [
            RecoveryError::InvalidName,
            RecoveryError::InvalidRequest,
            RecoveryError::TooLarge,
            RecoveryError::Full,
            RecoveryError::NotFound,
            RecoveryError::Unavailable,
            RecoveryError::Io,
        ] {
            assert!(!error.to_string().contains('/'), "{error}");
        }
    }
}
